INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3302-4000-8000-000000000002', 'b1b2c3d4-3333-4000-8000-000000000003', 2, 'Oração de Entrega', 'Colocar-se diante de Deus', '{"text": "Senhor Jesus Cristo,\nV\u00f3s que me chamais pelo nome,\nque me conheceis antes de eu nascer,\nconcedei-me a gra\u00e7a de ouvir Vossa voz\nno sil\u00eancio do meu cora\u00e7\u00e3o.\n\nTirai de mim todo medo,\ntoda resist\u00eancia,\ntodo apego \u00e0 minha vontade pr\u00f3pria.\n\nQuero apenas o que V\u00f3s quereis para mim.\nFazei de mim instrumento d\u00f3cil\nnas Vossas m\u00e3os.\n\nMaria, M\u00e3e do discernimento,\nque disseste o \"sim\" perfeito,\nintercessora por mim nesta jornada.\n\nAm\u00e9m.", "instruction": "Reze esta ora\u00e7\u00e3o lentamente, em ambiente silencioso. Repita as partes que tocarem seu cora\u00e7\u00e3o."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;